import{c as r,Q as a,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Free Energy Heuristics: Fast-And-Frugal Cognition as Active Inference Under Uncertain Precision","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.15877","title":"Free Energy Heuristics: Fast-And-Frugal Cognition as Active Inference Under Uncertain Precision","archived_date":"2026-07-03T00:00:00.000Z","arxiv_id":2606.15877,"authors":["Alex Bogdan"],"domain":"active-inference","published_date":"2026-06-14T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-06-14-free-energy-heuristics-active-inference-2606-15877.md","filePath":"research/papers/2026-06-14-free-energy-heuristics-active-inference-2606-15877.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-06-14-free-energy-heuristics-active-inference-2606-15877.md"};function c(s,e,o,d,u,f){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="free-energy-heuristics-fast-and-frugal-cognition-as-active-inference-under-uncertain-precision" tabindex="-1">Free Energy Heuristics: Fast-And-Frugal Cognition as Active Inference Under Uncertain Precision <a class="header-anchor" href="#free-energy-heuristics-fast-and-frugal-cognition-as-active-inference-under-uncertain-precision" aria-label="Permalink to &quot;Free Energy Heuristics: Fast-And-Frugal Cognition as Active Inference Under Uncertain Precision&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文探討為何 chain-of-thought（CoT）推理在某些任務上提升 LLM 表現，卻在另一些任務上使表現惡化。 作者提出「meta-uncertainty」（對自身證據可靠性的不確定性）是決定性因素，並證明： 在 precision prior 為 heavy-tailed 分佈時，最小化「預期自由能」的策略在累積有限數量的 高效度線索後便停止整合更多資訊 —— 此行為在特定條件下等同「take-the-best」捷思法， 統一了 fast-and-frugal cognition 與 active inference 兩套理論。</p><p>實證研究（FEH-79 benchmark）涵蓋 7 個模型、7,875 筆回應： 高 meta-uncertainty 題目隨推理鏈變長準確率顯著下降（高不確定性情境下降 17.3 個百分點）， 而答案明確的題目則無此劣化。此框架調和了 Bayesian 與 fast-and-frugal 兩傳統， 將「less-is-more」現象重新詮釋為 meta-uncertainty 的指標，而非 Bayesian 認知的反例。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>以 active inference / 自由能原理視角重新解釋 LLM CoT 推理的失效模式， 是「非主流智能理論框架 × 主流 LLM 現象」的交叉點，workspace 既有覆蓋集合中 <code>active-inference</code> / <code>free-energy</code> 命中 0 次，且此篇直接對應 workspace 高度關注的 CoT/reasoning 主題，提供全新理論透鏡，槓桿潛力高。</p>',6)])])}const p=r(t,[["render",c]]);export{h as __pageData,p as default};
